// The C++ of OrderBook.Money, ported from C# (CodeCoreMorph, D-78).
#ifndef ORDER_BOOK_MONEY_HPP
#define ORDER_BOOK_MONEY_HPP

#include <cstdint>
#include <string>

namespace order_book {

/// An amount in one currency, in minor units (cents).
class Money {
public:
    Money(std::int64_t cents, std::string currency);

    std::int64_t cents() const { return cents_; }
    const std::string& currency() const { return currency_; }

    Money plus(const Money& other) const;
    Money times(std::int32_t quantity) const;

    bool equals(const Money& other) const;
    std::int32_t hash_code() const;
    std::string to_string() const;

private:
    std::int64_t cents_;
    std::string currency_;
};

}  // namespace order_book

#endif

// The C++ of OrderBook.Money, ported from C# (CodeCoreMorph, D-78).
#include "money.hpp"

#include <functional>
#include <utility>

#include "codecoremorph_exceptions.hpp"

namespace order_book {

namespace {

// C# integer arithmetic is unchecked here and wraps: do it in unsigned types.
std::int64_t wrap(std::uint64_t value) { return static_cast<std::int64_t>(value); }

}  // namespace

Money::Money(std::int64_t cents, std::string currency)
    : cents_(cents), currency_(std::move(currency)) {}

Money Money::plus(const Money& other) const {
    if (other.currency_ != currency_) {
        throw ccm::InvalidOperationException("currency mismatch: " + currency_ + " and " +
                                             other.currency_);
    }
    return Money(wrap(static_cast<std::uint64_t>(cents_) + static_cast<std::uint64_t>(other.cents_)),
                 currency_);
}

Money Money::times(std::int32_t quantity) const {
    return Money(wrap(static_cast<std::uint64_t>(cents_) *
                      static_cast<std::uint64_t>(static_cast<std::int64_t>(quantity))),
                 currency_);
}

bool Money::equals(const Money& other) const {
    return cents_ == other.cents_ && currency_ == other.currency_;
}

// Equal amounts hash equally. (.NET randomizes string hashes per process, so no value of the C#
// was ever reproducible; this keeps its shape: the long's hash times 31 plus the string's.)
std::int32_t Money::hash_code() const {
    const auto bits = static_cast<std::uint64_t>(cents_);
    const auto long_hash = static_cast<std::uint32_t>(bits) ^ static_cast<std::uint32_t>(bits >> 32);
    const auto string_hash = static_cast<std::uint32_t>(std::hash<std::string>{}(currency_));
    return static_cast<std::int32_t>(long_hash * 31u + string_hash);
}

// "{0}.{1:00} {2}" with cents / 100 and cents % 100 (both truncate toward zero, as in C#); a
// negative remainder keeps its sign in front of its two digits.
std::string Money::to_string() const {
    const std::int64_t whole = cents_ / 100;
    std::int64_t rest = cents_ % 100;
    std::string text = std::to_string(whole) + ".";
    if (rest < 0) {
        text += '-';
        rest = -rest;
    }
    if (rest < 10) {
        text += '0';
    }
    text += std::to_string(rest);
    text += ' ';
    text += currency_;
    return text;
}

}  // namespace order_book

