/// One product of an order: so many units at a price.
class OrderLine {
public:
    /// The sku and the price may be null (an empty optional, an empty pointer), as in C#.
    OrderLine(std::optional<std::string> sku, std::int32_t quantity,
              std::shared_ptr<Money> unit_price);

    const std::optional<std::string>& sku() const { return sku_; }
    std::int32_t quantity() const { return quantity_; }
    const std::shared_ptr<Money>& unit_price() const { return unit_price_; }
    Money total() const;

    bool equals(const OrderLine& other) const;
    std::int32_t hash_code() const;

private:
    std::optional<std::string> sku_;
    std::int32_t quantity_;
    std::shared_ptr<Money> unit_price_;
};

