// The C++ of OrderBook.OrderLine, ported from C# (CodeCoreMorph, D-78).
#include "order_line.hpp"

#include <functional>
#include <utility>

#include "codecoremorph_exceptions.hpp"

namespace order_book {

namespace {

// What C# throws when the price, which the constructor lets be null, is used.
const Money& price_of(const std::shared_ptr<Money>& price) {
    if (!price) {
        throw ccm::NullReferenceException("Object reference not set to an instance of an object.");
    }
    return *price;
}

}  // namespace

OrderLine::OrderLine(std::optional<std::string> sku, std::int32_t quantity,
                     std::shared_ptr<Money> unit_price)
    : sku_(std::move(sku)), quantity_(quantity), unit_price_(std::move(unit_price)) {
    if (quantity <= 0) {
        throw ccm::ArgumentOutOfRangeException("quantity", "a line has at least one unit");
    }
}

Money OrderLine::total() const { return price_of(unit_price_).times(quantity_); }

bool OrderLine::equals(const OrderLine& other) const {
    if (sku_ != other.sku_ || quantity_ != other.quantity_) {
        return false;
    }
    const Money& mine = price_of(unit_price_);
    return other.unit_price_ != nullptr && mine.equals(*other.unit_price_);
}

// sku hash (0 for null) * 31 + quantity, * 31 + the price's hash, unchecked, as in C#.
std::int32_t OrderLine::hash_code() const {
    std::uint32_t hash = sku_ ? static_cast<std::uint32_t>(std::hash<std::string>{}(*sku_)) : 0u;
    hash = hash * 31u + static_cast<std::uint32_t>(quantity_);
    return static_cast<std::int32_t>(hash * 31u +
                                     static_cast<std::uint32_t>(price_of(unit_price_).hash_code()));
}

}  // namespace order_book

