// The C++ of OrderBook.Order, ported from C# (CodeCoreMorph, D-78).
#include "order.hpp"

#include <utility>

#include "codecoremorph_exceptions.hpp"

namespace order_book {

namespace {

// What C# throws when a line the list holds as null is used.
const OrderLine& line_of(const std::shared_ptr<OrderLine>& line) {
    if (!line) {
        throw ccm::NullReferenceException("Object reference not set to an instance of an object.");
    }
    return *line;
}

}  // namespace

Order::Order(std::optional<std::string> id) : id_(std::move(id)), status_(OrderStatus::Open) {}

// "order " + id + " is " + StatusText(): a null id adds nothing, as in C#.
std::string Order::described() const { return "order " + id_.value_or("") + " is " + status_text(); }

void Order::add(std::shared_ptr<OrderLine> line) {
    if (status_ != OrderStatus::Open) {
        throw ccm::InvalidOperationException(described());
    }
    lines_.push_back(std::move(line));
}

std::optional<Money> Order::total() const {
    if (lines_.empty()) {
        return std::nullopt;
    }
    Money total = line_of(lines_[0]).total();
    for (std::size_t i = 1; i < lines_.size(); ++i) {
        total = total.plus(line_of(lines_[i]).total());
    }
    return total;
}

std::shared_ptr<OrderLine> Order::find(const std::optional<std::string>& sku) const {
    for (const auto& line : lines_) {
        if (line_of(line).sku() == sku) {
            return line;
        }
    }
    return nullptr;
}

void Order::pay() { move(OrderStatus::Open, OrderStatus::Paid); }

void Order::ship() { move(OrderStatus::Paid, OrderStatus::Shipped); }

void Order::cancel() {
    if (status_ == OrderStatus::Shipped) {
        throw ccm::InvalidOperationException("order " + id_.value_or("") + " has shipped");
    }
    status_ = OrderStatus::Cancelled;
}

std::string Order::status_text() const {
    switch (status_) {
        case OrderStatus::Open:
            return "open";
        case OrderStatus::Paid:
            return "paid";
        case OrderStatus::Shipped:
            return "shipped";
        case OrderStatus::Cancelled:
            break;
    }
    return "cancelled";
}

void Order::move(OrderStatus from, OrderStatus to) {
    if (status_ != from) {
        throw ccm::InvalidOperationException(described());
    }
    status_ = to;
}

}  // namespace order_book

