using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Runtime.Serialization;
using CodeCoreMorph.Interop;

namespace OrderBook
{
    public enum OrderStatus
    {
        Open,
        Paid,
        Shipped,
        Cancelled,
    }

    /// <summary>An order: its lines, and where it is between open and shipped.</summary>
    [Serializable]
    public class Order
    {
        // The native object. Not serialized (Book.Snapshot copies a book through a
        // BinaryFormatter): the order's values travel in the fields below, and the native object
        // is made again, and brought to the same state, the first time a copy read back needs it.
        [NonSerialized]
        private order_book_OrderHandle native;
        private string serializedId;
        private OrderStatus serializedStatus;
        private string serializedNote;
        private List<OrderLine> serializedLines;

        public Order(string id)
        {
            order_book_OrderHandle handle;
            CcmInterop.Check(CcmNative.order_book_Order_new(id, out handle));
            native = handle;
            CcmObjects.Register(handle.Key, this);
        }

        private Order(order_book_OrderHandle handle)
        {
            native = handle;
        }

        internal order_book_OrderHandle Handle
        {
            get
            {
                if (native == null)
                {
                    Restore();
                }
                return native;
            }
        }

        internal static Order FromHandle(order_book_OrderHandle h)
        {
            return CcmObjects.Wrap(h, x => new Order(x));
        }

        internal static order_book_OrderHandle HandleOf(Order order)
        {
            return order == null ? order_book_OrderHandle.Null : order.Handle;
        }

        [OnSerializing]
        private void OnSerializing(StreamingContext context)
        {
            serializedId = Id;
            serializedStatus = Status;
            serializedNote = Note;
            serializedLines = new List<OrderLine>(Lines);
        }

        // Replays what was serialized: the lines while the order is open, then its way to its status.
        private void Restore()
        {
            order_book_OrderHandle handle;
            CcmInterop.Check(CcmNative.order_book_Order_new(serializedId, out handle));
            CcmInterop.Check(CcmNative.order_book_Order_set_note(handle, serializedNote));
            if (serializedLines != null)
            {
                foreach (OrderLine line in serializedLines)
                {
                    CcmInterop.Check(CcmNative.order_book_Order_add(handle, OrderLine.HandleOf(line)));
                }
            }
            switch (serializedStatus)
            {
                case OrderStatus.Paid:
                    CcmInterop.Check(CcmNative.order_book_Order_pay(handle));
                    break;
                case OrderStatus.Shipped:
                    CcmInterop.Check(CcmNative.order_book_Order_pay(handle));
                    CcmInterop.Check(CcmNative.order_book_Order_ship(handle));
                    break;
                case OrderStatus.Cancelled:
                    CcmInterop.Check(CcmNative.order_book_Order_cancel(handle));
                    break;
            }
            native = handle;
            CcmObjects.Register(handle.Key, this);
        }

        public string Id
        {
            get
            {
                IntPtr result;
                CcmInterop.Check(CcmNative.order_book_Order_id(Handle, out result));
                return CcmInterop.TakeString(result);
            }
        }

        public OrderStatus Status
        {
            get
            {
                int result;
                CcmInterop.Check(CcmNative.order_book_Order_status(Handle, out result));
                return (OrderStatus)result;
            }
        }

        /// <summary>A free-text note; null until someone writes one.</summary>
        public string Note
        {
            get
            {
                IntPtr result;
                CcmInterop.Check(CcmNative.order_book_Order_note(Handle, out result));
                return CcmInterop.TakeString(result);
            }
            set
            {
                CcmInterop.Check(CcmNative.order_book_Order_set_note(Handle, value));
            }
        }

        public IList<OrderLine> Lines
        {
            get
            {
                int count;
                CcmInterop.Check(CcmNative.order_book_Order_lines_count(Handle, out count));
                List<OrderLine> lines = new List<OrderLine>(count);
                for (int i = 0; i < count; i++)
                {
                    order_book_OrderLineHandle line;
                    CcmInterop.Check(CcmNative.order_book_Order_lines_at(Handle, i, out line));
                    lines.Add(OrderLine.FromHandle(line));
                }
                return new ReadOnlyCollection<OrderLine>(lines);
            }
        }

        public void Add(OrderLine line)
        {
            CcmInterop.Check(CcmNative.order_book_Order_add(Handle, OrderLine.HandleOf(line)));
        }

        /// <summary>The order's total, or null for an order without lines.</summary>
        public Money Total()
        {
            order_book_MoneyHandle result;
            CcmInterop.Check(CcmNative.order_book_Order_total(Handle, out result));
            return Money.FromHandle(result);
        }

        public OrderLine Find(string sku)
        {
            order_book_OrderLineHandle result;
            CcmInterop.Check(CcmNative.order_book_Order_find(Handle, sku, out result));
            return OrderLine.FromHandle(result);
        }

        public void Pay()
        {
            CcmInterop.Check(CcmNative.order_book_Order_pay(Handle));
        }

        public void Ship()
        {
            CcmInterop.Check(CcmNative.order_book_Order_ship(Handle));
        }

        public void Cancel()
        {
            CcmInterop.Check(CcmNative.order_book_Order_cancel(Handle));
        }

        public string StatusText()
        {
            IntPtr result;
            CcmInterop.Check(CcmNative.order_book_Order_status_text(Handle, out result));
            return CcmInterop.TakeString(result);
        }
    }
}

