#include "book.hpp"

#include <algorithm>
#include <cstddef>
#include <utility>

#include "codecoremorph_exceptions.hpp"

namespace order_book {

namespace {

bool is_space(char c) { return c == ' ' || (c >= '\t' && c <= '\r'); }

[[noreturn]] void bad_format() {
    throw ccm::FormatException("Input string was not in a correct format.");
}

[[noreturn]] void null_reference() {
    throw ccm::NullReferenceException("Object reference not set to an instance of an object.");
}

// long.Parse / int.Parse(text, CultureInfo.InvariantCulture): optional white space, an optional
// sign, digits, optional white space. positive_max is the largest value.
std::int64_t parse_integer(const std::string& text, std::uint64_t positive_max,
                           const char* overflow_message) {
    std::size_t begin = 0;
    std::size_t end = text.size();
    while (begin < end && is_space(text[begin])) ++begin;
    while (end > begin && is_space(text[end - 1])) --end;
    bool negative = false;
    if (begin < end && (text[begin] == '-' || text[begin] == '+')) {
        negative = text[begin] == '-';
        ++begin;
    }
    if (begin == end) bad_format();
    for (std::size_t i = begin; i < end; ++i) {
        if (text[i] < '0' || text[i] > '9') bad_format();
    }
    const std::uint64_t limit = positive_max + (negative ? 1u : 0u);
    std::uint64_t value = 0;
    for (std::size_t i = begin; i < end; ++i) {
        const auto digit = static_cast<std::uint64_t>(text[i] - '0');
        if (value > (limit - digit) / 10) throw ccm::OverflowException(overflow_message);
        value = value * 10 + digit;
    }
    return negative ? static_cast<std::int64_t>(0 - value) : static_cast<std::int64_t>(value);
}

std::int64_t parse_long(const std::string& text) {
    return parse_integer(text, 9223372036854775807ull,
                         "Value was either too large or too small for an Int64.");
}

std::int32_t parse_int(const std::string& text) {
    return static_cast<std::int32_t>(
        parse_integer(text, 2147483647ull, "Value was either too large or too small for an Int32."));
}

// fields[index]: an index past the end throws, as an array's does.
const std::string& field(const std::vector<std::string>& fields, std::size_t index) {
    if (index >= fields.size()) {
        throw ccm::IndexOutOfRangeException("Index was outside the bounds of the array.");
    }
    return fields[index];
}

std::vector<std::string> split_commas(const std::string& row) {
    std::vector<std::string> fields;
    std::size_t start = 0;
    while (true) {
        const std::size_t comma = row.find(',', start);
        if (comma == std::string::npos) {
            fields.push_back(row.substr(start));
            return fields;
        }
        fields.push_back(row.substr(start, comma - start));
        start = comma + 1;
    }
}

}  // namespace

std::shared_ptr<Order> Book::open(const std::string& id) {
    if (orders_.find(id) != orders_.end()) {
        throw ccm::ArgumentException("order " + id + " exists", "id");
    }
    auto order = std::make_shared<Order>(id);
    orders_.emplace(id, order);
    return order;
}

std::shared_ptr<Order> Book::get(const std::string& id) const {
    const auto found = orders_.find(id);
    return found == orders_.end() ? nullptr : found->second;
}

// Ordinal order, by the bytes of the UTF-8 (the same as by UTF-16 units for what is not
// supplementary-plane text).
std::vector<std::string> Book::ids() const {
    std::vector<std::string> ids;
    ids.reserve(orders_.size());
    for (const auto& entry : orders_) {
        ids.push_back(entry.first);
    }
    std::sort(ids.begin(), ids.end());
    return ids;
}

std::shared_ptr<Book> Book::snapshot() const {
    auto copy = std::make_shared<Book>();
    // What the original shares (a line in two orders, a price in two lines) stays shared in the copy.
    std::unordered_map<const Money*, std::shared_ptr<Money>> prices;
    std::unordered_map<const OrderLine*, std::shared_ptr<OrderLine>> lines;
    const auto copy_price = [&prices](const std::shared_ptr<Money>& price) {
        if (!price) return std::shared_ptr<Money>();
        auto& slot = prices[price.get()];
        if (!slot) slot = std::make_shared<Money>(*price);
        return slot;
    };
    const auto copy_line = [&lines, &copy_price](const std::shared_ptr<OrderLine>& line) {
        if (!line) return std::shared_ptr<OrderLine>();
        auto& slot = lines[line.get()];
        if (!slot) {
            slot = std::make_shared<OrderLine>(line->sku(), line->quantity(),
                                               copy_price(line->unit_price()));
        }
        return slot;
    };
    for (const auto& entry : orders_) {
        const Order& order = *entry.second;
        auto order_copy = std::make_shared<Order>(order.id());
        order_copy->set_note(order.note());
        for (const auto& line : order.lines()) {
            order_copy->add(copy_line(line));
        }
        switch (order.status()) {
            case OrderStatus::Open:
                break;
            case OrderStatus::Paid:
                order_copy->pay();
                break;
            case OrderStatus::Shipped:
                order_copy->pay();
                order_copy->ship();
                break;
            case OrderStatus::Cancelled:
                order_copy->cancel();
                break;
        }
        copy->orders_.emplace(entry.first, std::move(order_copy));
    }
    return copy;
}

std::string Book::export_text() const {
    std::string text;
    for (const std::string& id : ids()) {
        const Order& order = *orders_.at(id);
        for (const auto& line : order.lines()) {
            if (!line) null_reference();
            text += id + "," + order.status_text() + "," + line->sku().value_or("") + ",";
            text += std::to_string(line->quantity()) + ",";
            if (!line->unit_price()) null_reference();
            text += std::to_string(line->unit_price()->cents());
            text += "," + line->unit_price()->currency() + "\n";
        }
    }
    return text;
}

std::shared_ptr<Book> Book::import_text(const std::string& text) {
    auto book = std::make_shared<Book>();
    std::size_t position = 0;
    while (position < text.size()) {
        // Rows end at \n, \r or \r\n; an empty row is skipped.
        const std::size_t end = text.find_first_of("\r\n", position);
        const std::string row = text.substr(position, end == std::string::npos ? end : end - position);
        position = end == std::string::npos ? text.size() : end + 1;
        if (row.empty()) {
            continue;
        }
        const std::vector<std::string> fields = split_commas(row);
        std::shared_ptr<Order> order = book->get(field(fields, 0));
        if (!order) {
            order = book->open(field(fields, 0));
        }
        const std::int64_t cents = parse_long(field(fields, 4));
        auto price = std::make_shared<Money>(cents, field(fields, 5));
        const std::string& sku = field(fields, 2);
        const std::int32_t quantity = parse_int(field(fields, 3));
        order->add(std::make_shared<OrderLine>(sku, quantity, std::move(price)));
    }
    return book;
}

void Book::adopt(std::shared_ptr<Order> order) {
    if (!order) {
        throw ccm::ArgumentNullException("order");
    }
    if (!order->id()) {
        throw ccm::ArgumentNullException("key");
    }
    const std::string id = *order->id();
    if (!orders_.emplace(id, std::move(order)).second) {
        throw ccm::ArgumentException("order " + id + " exists", "id");
    }
}

}  // namespace order_book

