#include "book.hpp"
#include "money.hpp"
#include "order.hpp"
#include "order_status.hpp"

namespace order_book {

/// Plain-text summaries of orders.
class Report {
public:
    Report() = delete;

    // Describe(object): one overload per kind of value the C# tells apart; anything else (a null
    // included) is describe_unknown().
    static std::string describe(const std::string& text);
    static std::string describe(const Order& order);
    static std::string describe(const Money& money);
    static std::string describe_unknown();

    static bool is_final(OrderStatus status);

    static std::string table(const Book& book);

    /// The sku of each line, in order (an entry is empty for a null sku).
    static std::vector<std::optional<std::string>> skus(const Order& order);
};

}  // namespace order_book

#endif

// The C++ of OrderBook.Report, ported from C# (CodeCoreMorph, D-78).
#include "report.hpp"

#include "codecoremorph_exceptions.hpp"

namespace order_book {

std::string Report::describe(const std::string& text) { return "text: " + text; }

// A null id adds nothing to the text, as in C#.
std::string Report::describe(const Order& order) {
    return "order " + order.id().value_or("") + " (" + order.status_text() + ")";
}

std::string Report::describe(const Money& money) { return "amount " + money.to_string(); }

std::string Report::describe_unknown() { return "unknown"; }

bool Report::is_final(OrderStatus status) {
    return status == OrderStatus::Shipped || status == OrderStatus::Cancelled;
}

std::string Report::table(const Book& book) {
    std::string text = "id\tstatus\ttotal\n";
    for (const std::string& id : book.ids()) {
        const std::shared_ptr<Order> order = book.get(id);
        const std::optional<Money> total = order->total();
        text += id + "\t" + order->status_text() + "\t";
        text += total.has_value() ? total->to_string() : std::string("-");
        text += "\n";
    }
    return text;
}

std::vector<std::optional<std::string>> Report::skus(const Order& order) {
    std::vector<std::optional<std::string>> skus;
    skus.reserve(order.lines().size());
    for (const auto& line : order.lines()) {
        if (!line) {
            throw ccm::NullReferenceException("Object reference not set to an instance of an object.");
        }
        skus.push_back(line->sku());
    }
    return skus;
}

}  // namespace order_book

