    return bridge::guard([&] { bridge::out_str(result, Report::describe_unknown()); });
}

ccm_status order_book_Report_is_final(int32_t status, bool *result) {
    return bridge::guard(
        [&] { *result = Report::is_final(static_cast<order_book::OrderStatus>(status)); });
}

ccm_status order_book_Report_table(const order_book_Book *book, char **result) {
    return bridge::guard([&] { bridge::out_str(result, Report::table(*bridge::from_handle(book))); });
}

ccm_status order_book_Report_skus_count(const order_book_Order *order, int32_t *result) {
    return bridge::guard([&] {
        *result = static_cast<int32_t>(Report::skus(*bridge::from_handle(order)).size());
    });
}

ccm_status order_book_Report_skus_at(const order_book_Order *order, int32_t index, char **result) {
    return bridge::guard([&] {
        const auto skus = Report::skus(*bridge::from_handle(order));
        if (index < 0 || static_cast<std::size_t>(index) >= skus.size()) {
            throw ccm::ArgumentOutOfRangeException("index");
        }
        bridge::out_opt_str(result, skus[static_cast<std::size_t>(index)]);
