using System;
using System.Collections.Generic;
using CodeCoreMorph.Interop;

namespace OrderBook
{
    /// <summary>Plain-text summaries of orders.</summary>
    public static class Report
    {
        public static string Describe(object value)
        {
            IntPtr result;
            string text = value as string;
            if (text != null)
            {
                CcmInterop.Check(CcmNative.order_book_Report_describe_text(text, out result));
                return CcmInterop.TakeString(result);
            }
            Order order = value as Order;
            if (order != null)
            {
                CcmInterop.Check(CcmNative.order_book_Report_describe_order(Order.HandleOf(order), out result));
                return CcmInterop.TakeString(result);
            }
            Money money = value as Money;
            if (money != null)
            {
                CcmInterop.Check(CcmNative.order_book_Report_describe_money(Money.HandleOf(money), out result));
                return CcmInterop.TakeString(result);
            }
            CcmInterop.Check(CcmNative.order_book_Report_describe_unknown(out result));
            return CcmInterop.TakeString(result);
        }

        public static bool IsFinal(OrderStatus status)
        {
            bool result;
            CcmInterop.Check(CcmNative.order_book_Report_is_final((int)status, out result));
            return result;
        }

        public static string Table(Book book)
        {
            IntPtr result;
            CcmInterop.Check(CcmNative.order_book_Report_table(Book.HandleOf(book), out result));
            return CcmInterop.TakeString(result);
        }

        public static IList<string> Skus(Order order)
        {
            int count;
            CcmInterop.Check(CcmNative.order_book_Report_skus_count(Order.HandleOf(order), out count));
            if (count == 0)
            {
                return Array.Empty<string>();
            }
            List<string> skus = new List<string>();
            for (int i = 0; i < count; i++)
            {
                IntPtr sku;
                CcmInterop.Check(CcmNative.order_book_Report_skus_at(Order.HandleOf(order), i, out sku));
                skus.Add(CcmInterop.TakeString(sku));
            }
            return skus;
        }
    }
}

