    std::shared_ptr<Book> book = Book::import_text(sample()->export_text());
    ASSERT_EQ(2, book->count());
    const auto total = book->get("B-2")->total();
    ASSERT_TRUE(total.has_value() && total->equals(Money(150, "EUR")));
